const stateIcon={aprobado:'ti-check',rechazado:'ti-x',pendiente:'ti-clock',organizando:'ti-route',revision_director:'ti-user-check',notificada:'ti-bell',cancelada:'ti-ban'};
const stateLabel={aprobado:'Aprobado',rechazado:'Rechazado',pendiente:'Pendiente',organizando:'Organizando',revision_director:'En aprobación',notificada:'Visitante notificado',cancelada:'Cancelada'};
