const showModal=id=>{const el=byId(id);if(el){el.classList.add('open');el.setAttribute('aria-hidden','false')}};
const hideModal=id=>{const el=byId(id);if(el){el.classList.remove('open');el.setAttribute('aria-hidden','true');if(id==='pdfModal'){byId('pdfViewer').removeAttribute('src');byId('pdfDownloadLink').setAttribute('href','#');if(activeDocumentUrl){URL.revokeObjectURL(activeDocumentUrl);activeDocumentUrl=''}}}};
function notify(message,error=false){const box=byId('visitActionMessage');box.textContent=message;box.className='visit-action-message show'+(error?' error':'');setTimeout(()=>box.classList.remove('show'),4200)}
