async function openDocumentPreview(button){
    const viewer=byId('pdfViewer');
    const endpoint=`ver_pdf.php?tipo=${encodeURIComponent(button.dataset.documentType)}&file=${encodeURIComponent(button.dataset.document)}`;
    const downloadLink=byId('pdfDownloadLink');
    showModal('pdfModal');
    // La URL directa se incluye también en el modal para que el navegador
    // pueda mostrar el PDF con la sesión actual, sin depender de blobs.
    downloadLink.href=endpoint;
    downloadLink.download=button.dataset.document||'';
    viewer.src=endpoint;

    try{
        const response=await fetch(endpoint,{credentials:'same-origin',cache:'no-store'});
        const contentType=(response.headers.get('content-type')||'').toLowerCase();
        const isLogin=response.redirected&&/\/login(?:\.html|\/)?(?:\?|$)/i.test(response.url);

        if(isLogin||contentType.includes('text/html')){
            window.location.assign(response.redirected?response.url:'../../../login/cengisalas_logout.php');
            return;
        }
        if(!response.ok)throw new Error(`No fue posible abrir el archivo (${response.status}).`);

        // Se mantiene la URL directa como fuente del visor. El fetch solo
        // valida que la sesión tenga acceso y evita que un error de lectura
        // del blob deje una ventana vacía.
        if (!contentType.includes('pdf') && !contentType.startsWith('image/')) {
            throw new Error('El documento no tiene un formato compatible.');
        }
    }catch(error){
        // Si la sesión sigue válida, dejamos el enlace directo disponible:
        // algunos navegadores bloquean fetch de PDFs grandes aunque el
        // endpoint sí pueda abrirse en una pestaña.
        if (/sesión|login|autoriz|acceso/i.test(error.message||'')) {
            hideModal('pdfModal');
            notify(error.message||'No fue posible abrir el documento.',true);
        } else {
            notify('La vista previa no pudo cargarse; usa “Abrir / descargar”.',true);
        }
    }
}

