function badge(state,reviewable,id){const body=`<i class="ti ${stateIcon[state]||'ti-clock'}" aria-hidden="true"></i>${stateLabel[state]||state}${reviewable?' · Revisar':''}`;return reviewable?`<button type="button" class="badge ${state}" data-review="${id}">${body}</button>`:`<span class="badge ${state}">${body}</span>`}
function paymentBadge(payment){const paid=payment==='pagado';return `<span class="badge ${paid?'pagado':'pendiente'}"><i class="ti ${paid?'ti-circle-check':'ti-clock'}" aria-hidden="true"></i>${paid?'Pagado':'Pendiente'}</span>`}
function progressDots(row){const state=row?.estado||'pendiente',steps={pendiente:1,organizando:2,revision_director:3,aprobado:4,notificada:5},terminal=['rechazado','cancelada'].includes(state),filled=terminal?(state==='rechazado'?3:2):(steps[state]||1),label=terminal?(state==='rechazado'?'Solicitud rechazada':'Solicitud cancelada'):`${stateLabel[state]||state}: ${filled} de 5 pasos`;return `<span class="progress-dots ${terminal?'terminal':''}" role="img" aria-label="${escapeHtml(label)}" title="${escapeHtml(label)}">${Array.from({length:5},(_,index)=>`<span class="progress-dot ${index<filled?'filled':''} ${index===filled-1?'current':''} ${terminal&&index===filled-1?'danger':''}"></span>`).join('')}</span>`}
