function actionMenuItem(icon,label,attributes='',options={}){const disabled=options.disabled?'disabled':'',title=options.title?` title="${escapeHtml(options.title)}"`:'',tone=options.tone||'neutral',lock=options.lock&&options.disabled?'<i class="ti ti-lock mi-lock" aria-hidden="true"></i>':'';return `<button type="button" ${attributes} ${disabled}${title}><span class="mi-dot ${tone}"><i class="ti ${icon}" aria-hidden="true"></i></span><span>${escapeHtml(label)}</span>${lock}</button>`}
