  html+=actionMenuItem('ti-school','Gestionar sala',!inactive&&row.puedeSala?`data-room-request="${row.id}"`:'',{disabled:inactive||!row.puedeSala,title:!row.puedeSala?'Requiere permiso para gestionar salones.':(inactive?'La solicitud ya no está activa.':''),tone:'amarillo',lock:!row.puedeSala});
  if(row.estado==='revision_director'){html+='<hr>';html+=actionMenuItem('ti-circle-check','Aprobar (Director)',`data-director-decision="approve" data-request-id="${row.id}"`,{tone:'success'});html+=actionMenuItem('ti-x','Rechazar (Director)',`data-director-decision="reject" data-request-id="${row.id}"`,{tone:'naranja'});}
  html+='<hr>';
  if(paidVisit){const paymentReady=['aprobado','notificada'].includes(row.estado);html+=actionMenuItem('ti-cash','Gestionar pago',(row.puedePago&&paymentReady)?`data-payment-request="${row.id}"`:'',{disabled:!row.puedePago||!paymentReady,title:!row.puedePago?'Requiere permiso de Administración.':(!paymentReady?'Disponible cuando la visita esté aprobada.':''),tone:'naranja',lock:!row.puedePago});}
  html+=actionMenuItem('ti-history','Ver seguimiento',`data-request-tracking="${row.id}"`,{tone:'accent'});
  if(row.puedeCorreo)html+=row.correoEnviado?actionMenuItem('ti-check','Correo enviado','',{disabled:true,tone:'success'}):actionMenuItem('ti-send','Enviar correo',`data-send-mail="${row.id}"`,{tone:'success'});
  if(row.puedeOcultar){html+='<hr>';html+=actionMenuItem('ti-eye-off','Ocultar solicitud',`data-hide-request="${row.id}"`,{tone:'naranja'});}
