function openActionsMenu(button,id){const row=findRow(id);if(!row)return;const root=byId('actionsMenuRoot'),wasOpen=button.getAttribute('aria-expanded')==='true';closeActionsMenu();if(wasOpen)return;root.innerHTML=actionsMenuHTML(row);root.setAttribute('aria-hidden','false');button.setAttribute('aria-expanded','true');const menu=root.firstElementChild,rect=button.getBoundingClientRect();let left=Math.min(rect.right-menu.offsetWidth,window.innerWidth-menu.offsetWidth-8);left=Math.max(8,left);let top=rect.bottom+6;if(top+menu.offsetHeight>window.innerHeight-8)top=Math.max(8,rect.top-menu.offsetHeight-6);menu.style.left=`${left}px`;menu.style.top=`${top}px`}
