function openVisitorList(id){const row=findRow(id);if(!row)return;byId('visitorListTitle').textContent=`Listado de visitantes · solicitud #${row.id}`;const names=visitorNamesForRow(row),room=row.sala?`${row.sala.nombre} · ${row.sala.distribucion}`:'Sin salón asignado';byId('visitorListBody').innerHTML=`<div class="visitor-list-meta"><div><small>Tipo de visita</small><strong>${escapeHtml(visitTypeLabel(row.tipo))}</strong></div><div><small>Solicitante</small><strong>${escapeHtml(row.nombre)}</strong></div><div><small>Institución</small><strong>${escapeHtml(row.inst)}</strong></div><div><small>Fecha y hora</small><strong>${escapeHtml(row.fecha)} · ${escapeHtml(row.hora)}</strong></div><div><small>Salón</small><strong>${escapeHtml(room)}</strong></div><div><small>Total registrado</small><strong>${names.length||row.vis} visitantes</strong></div></div><div class="visitor-list-table-wrap"><table class="visitor-list-table"><thead><tr><th>No.</th><th>Nombre completo</th></tr></thead><tbody>${visitorRowsHtml(row)}</tbody></table></div>`;byId('exportVisitorPdf').dataset.requestId=String(row.id);byId('exportVisitorExcel').dataset.requestId=String(row.id);showModal('visitorListModal')}
