function trackingItem(title,detail,state=''){return `<div class="timeline-item ${state}"><span class="timeline-dot"><i class="ti ${state==='done'?'ti-check':state==='danger'?'ti-x':'ti-clock'}" aria-hidden="true"></i></span><strong>${escapeHtml(title)}</strong><small>${escapeHtml(detail)}</small></div>`}
