async function updatePayment(button){if(!activePaymentRow)return;setBusy(button,true);try{const response=await fetch('actualizar_pago.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({csrf,id_solicitud:activePaymentRow.id,estado:button.dataset.paymentState})}),body=await response.json().catch(()=>({}));if(!response.ok||!body.success)throw new Error(body.error||'No fue posible actualizar el pago.');notify('Estado del pago actualizado.');setTimeout(()=>location.reload(),650)}catch(error){notify(error.message,true);setBusy(button,false)}}
const normalizeText=value=>String(value??'').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'');
const formatMoney=value=>'Q'+Number(value||0).toLocaleString('es-GT',{minimumFractionDigits:2,maximumFractionDigits:2});
const paymentKey=row=>Number(row.total)>0?(row.pago==='pagado'?'pagado':'pendiente'):'sin_costo';
const REVIEW_STATES=['pendiente','organizando','revision_director'];
const STATUS_TABS=[['todas','Todas'],['pendiente','Pendiente'],['organizando','Organizando'],['revision_director','En aprobación'],['aprobado','Aprobado'],['notificada','Notificado'],['rechazado','Rechazado'],['cancelada','Cancelada']];
const PAGE_SIZE=20;
let requestSort={key:'id',dir:'desc'},requestPage=1;
function requestFilters(){return{query:normalizeText(byId('searchInput').value.trim()),state:byId('statusFilter').value,type:byId('typeFilter').value,payment:byId('paymentFilter')?.value||'todos',from:byId('dateFromFilter')?.value||'',to:byId('dateToFilter')?.value||''}}
function filteredData(ignoreStatus=false){const f=requestFilters();return data.filter(row=>(ignoreStatus||f.state==='todas'||row.estado===f.state)&&(f.type==='todos'||row.tipo===f.type)&&(f.payment==='todos'||paymentKey(row)===f.payment)&&(!f.from||(row.fecha&&row.fecha>=f.from))&&(!f.to||(row.fecha&&row.fecha<=f.to))&&(!f.query||normalizeText(`${row.id} ${row.nombre} ${row.inst} ${row.areas.join(' ')} ${row.visitantes||''} ${row.correo} ${row.tel||''}`).includes(f.query)))}
function sortedRequests(rows){const {key,dir}=requestSort,factor=dir==='asc'?1:-1;return [...rows].sort((a,b)=>{let x,y;if(key==='nombre'){return factor*String(a.nombre).localeCompare(String(b.nombre),'es',{sensitivity:'base'})||(b.id-a.id)}if(key==='total'){x=Number(a.total)||0;y=Number(b.total)||0}else if(key==='fecha'){x=`${a.fecha||''} ${a.hora||''}`;y=`${b.fecha||''} ${b.hora||''}`;return factor*x.localeCompare(y)||(b.id-a.id)}else{x=Number(a.id);y=Number(b.id)}return factor*(x-y)||(b.id-a.id)})}
function requestFiltersActive(){const f=requestFilters();return Boolean(f.query||f.state!=='todas'||f.type!=='todos'||f.payment!=='todos'||f.from||f.to)}
function prettyVisitDate(value){const match=String(value||'').match(/^(\d{4})-(\d{2})-(\d{2})/);if(!match)return{date:value||'Sin fecha',weekday:''};const date=new Date(Date.UTC(+match[1],+match[2]-1,+match[3]));return{date:new Intl.DateTimeFormat('es-GT',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}).format(date).replace('.',''),weekday:new Intl.DateTimeFormat('es-GT',{weekday:'long',timeZone:'UTC'}).format(date)}}
function renderRequestStats(rows){const box=byId('requestStats');if(!box)return;const visitors=rows.reduce((sum,row)=>sum+(Number(row.vis)||0),0),amount=rows.filter(row=>!['rechazado','cancelada'].includes(row.estado)).reduce((sum,row)=>sum+(Number(row.total)||0),0),review=rows.filter(row=>REVIEW_STATES.includes(row.estado)).length,payPending=rows.filter(row=>['aprobado','notificada'].includes(row.estado)&&paymentKey(row)==='pendiente'),approved=rows.filter(row=>['aprobado','notificada'].includes(row.estado)).length;const card=(cls,label,value,sub)=>`<div class="req-stat ${cls}"><span>${label}</span><strong>${value}</strong><small>${sub}</small></div>`;box.innerHTML=card('','Solicitudes',rows.length,requestFiltersActive()?`de ${data.length} en total`:'Total registradas')+card('warn','Por revisar',review,'Pendientes, organizando o en aprobación')+card('','Aprobadas',approved,'Incluye visitantes notificados')+card('','Visitantes',visitors.toLocaleString('es-GT'),'Personas en las solicitudes')+card(payPending.length?'alert':'money','Monto cotizado',formatMoney(amount),payPending.length?`${payPending.length} ${payPending.length===1?'pago pendiente':'pagos pendientes'} · ${formatMoney(payPending.reduce((s,r)=>s+(Number(r.total)||0),0))}`:'Sin pagos pendientes')}
function renderStatusTabs(){const box=byId('statusTabs');if(!box)return;const base=filteredData(true),current=byId('statusFilter').value;box.innerHTML=STATUS_TABS.map(([value,label])=>{const count=value==='todas'?base.length:base.filter(row=>row.estado===value).length;return `<button type="button" data-status-tab="${value}" class="${current===value?'active':''}" aria-pressed="${current===value}" ${count||value==='todas'||current===value?'':'disabled'}>${label} <b>${count}</b></button>`}).join('')}
function renderPager(total){const pager=byId('requestPager');if(!pager)return;const pages=Math.max(1,Math.ceil(total/PAGE_SIZE));if(total<=PAGE_SIZE){pager.hidden=true;pager.innerHTML='';return}const start=(requestPage-1)*PAGE_SIZE+1,end=Math.min(total,requestPage*PAGE_SIZE),numbers=[];for(let page=1;page<=pages;page++){if(page===1||page===pages||Math.abs(page-requestPage)<=1)numbers.push(page);else if(numbers[numbers.length-1]!=='…')numbers.push('…')}pager.hidden=false;pager.innerHTML=`<span>Mostrando ${start}–${end} de ${total}</span><div><button type="button" data-page="${requestPage-1}" ${requestPage===1?'disabled':''} aria-label="Página anterior"><i class="ti ti-chevron-left" aria-hidden="true"></i></button>${numbers.map(page=>page==='…'?'<span>…</span>':`<button type="button" data-page="${page}" class="${page===requestPage?'active':''}" ${page===requestPage?'aria-current="page"':''}>${page}</button>`).join('')}<button type="button" data-page="${requestPage+1}" ${requestPage===pages?'disabled':''} aria-label="Página siguiente"><i class="ti ti-chevron-right" aria-hidden="true"></i></button></div>`}
function refreshRequests(resetPage=true){if(resetPage)requestPage=1;renderTable()}
function renderTable(){const rows=sortedRequests(filteredData()),pages=Math.max(1,Math.ceil(rows.length/PAGE_SIZE));requestPage=Math.min(Math.max(1,requestPage),pages);renderRequestStats(rows);renderStatusTabs();document.querySelectorAll('.sort-btn').forEach(button=>{const active=button.dataset.sort===requestSort.key;if(active)button.dataset.dir=requestSort.dir;else delete button.dataset.dir;button.closest('th')?.setAttribute('aria-sort',active?(requestSort.dir==='asc'?'ascending':'descending'):'none')});const clear=byId('clearRequestFilters');if(clear)clear.hidden=!requestFiltersActive();byId('resultCount').textContent=`${rows.length} ${rows.length===1?'solicitud encontrada':'solicitudes encontradas'}`;renderPager(rows.length);if(!rows.length){byId('requestsBody').innerHTML=`<tr><td colspan="8"><div class="empty-state"><i class="ti ti-search-off" aria-hidden="true"></i>No se encontraron solicitudes con esos criterios.${requestFiltersActive()?' <button type="button" class="btn" data-clear-filters style="margin-left:8px">Limpiar filtros</button>':''}</div></td></tr>`;return}byId('requestsBody').innerHTML=rows.slice((requestPage-1)*PAGE_SIZE,requestPage*PAGE_SIZE).map(row=>{const actions=iconButton('ti-dots-vertical','Más acciones',`data-action-menu="${row.id}" aria-expanded="false"`,'actions-trigger'),reviewable=row.puedeRevisar&&!['rechazado','cancelada'].includes(row.estado);return `<tr><td class="id-cell">${row.id}</td><td>${typeChip(row.tipo)}</td><td class="name-cell"><div class="primary">${escapeHtml(row.nombre)}</div><div class="secondary">${escapeHtml(row.inst)}</div></td><td class="areas-cell">${row.areas.map(chip).join('')||'<span class="secondary">Sin áreas</span>'}</td><td class="visit-cell"><div class="primary">${Number(row.total)>0?formatMoney(row.total):'Sin costo'}</div><div class="secondary">${row.vis} ${Number(row.vis)===1?'visitante':'visitantes'}</div>${Number(row.total)>0&&['aprobado','notificada'].includes(row.estado)?`<span class="pay-chip ${pa