function switchTab(tab){if(tab==='contactos')tab='areas';const tabs=['Solicitudes','Reportes','Areas','BaseDatos','Roles'];tabs.forEach(name=>{const key=name==='BaseDatos'?'basedatos':name.toLowerCase(),view=byId(`view${name}`),nav=byId(`nav${name}`);if(view)view.hidden=tab!==key;if(nav)nav.classList.toggle('active',tab===key)});if(tab==='reportes')renderReports();if(tab==='areas')renderAreas();if(tab==='basedatos')renderContactDatabase();if(tab==='roles')renderRoles()}
