const requestExcelRow=row=>({id:row.id,tipo:visitTypeLabel(row.tipo),estado:stateLabel[row.estado]||row.estado,fecha:row.fecha,dia:prettyVisitDate(row.fecha).weekday,hora:row.hora,nombre:row.nombre,inst:row.inst,correo:row.correo,tel:row.tel,areas:row.areas.join(', '),vis:Number(row.vis)||0,total:Number(row.total)||0,pago:paymentLabel(row),sala:row.sala?`${row.sala.nombre} · ${row.sala.distribucion}`:'',visitantes:visitorNamesForRow(row).join(', ')});
