const summaryColumns=label=>[{header:label,key:'grupo',width:28},{header:'Solicitudes',key:'solicitudes',type:'int'},{header:'Visitantes',key:'visitantes',type:'int'},{header:'Monto cotizado',key:'monto',type:'money'}];
