function renderReports(){const key=byId('monthSelect').value,rows=reportRows(),visitors=rows.reduce((sum,r)=>sum+r.vis,0),income=rows.reduce((sum,r)=>sum+r.total,0),activeDays=new Set(rows.map(r=>r.fecha)).size,average=activeDays?Math.round(visitors/activeDays):0;byId('metricCards').innerHTML=[['Visitantes del mes',visitors,'Solicitudes activas'],['Solicitudes',rows.length,key?'En '+monthLabel(key):'Sin información'],['Promedio diario',average,'Visitantes por día con actividad'],['Ingresos por visitas','Q'+income.toFixed(2),'Total facturado del mes']].map(card=>`<div class="metric-card"><div class="label">${card[0]}</div><div class="value">${card[1]}</div><div class="sub">${card[2]}</div></div>`).join('');const types=['cengicana','museo_azucar'];byId('typeMetricCards').innerHTML=types.map(type=>{const list=rows.filter(row=>row.tipo===type);return `<div class="metric-card"><div class="label">${escapeHtml(visitTypeLabel(type))}</div><div class="value">${list.length}</div><div class="sub">${list.reduce((sum,row)=>sum+row.vis,0)} visitantes</div></div>`}).join('');const daily={};rows.forEach(r=>daily[r.fecha]=(daily[r.fecha]||0)+r.vis);if(!key){byId('dailyBars').innerHTML='<div class="empty-state">Sin datos disponibles.</div>';byId('instTbody').innerHTML='<tr><td colspan="4" class="empty-state">Sin datos disponibles.</td></tr>';return}const [year,month]=key.split('-').map(Number),days=new Date(year,month,0).getDate(),max=Math.max(1,...Object.values(daily));let bars='';for(let day=1;day<=days;day++){const date=`${key}-${String(day).padStart(2,'0')}`,value=daily[date]||0,height=Math.max(2,Math.round(value/max*140));bars+=`<div class="bar-col" title="${date}: ${value} visitantes"><div class="bar" style="height:${height}px"></div><div class="bar-day">${day}</div></div>`}byId('dailyBars').innerHTML=bars;const institutions={};rows.forEach(r=>{institutions[r.inst]??={requests:0,visitors:0};institutions[r.inst].requests++;institutions[r.inst].visitors+=r.vis});const instRows=Ob