function downloadReport(event){const key=byId('monthSelect').value,rows=reportRows();if(!key||!rows.length)return notify('No hay visitas para el mes seleccionado.',true);runExcelExport(event?.currentTarget,()=>{const month=monthLabel(key).replace(/^./,c=>c.toUpperCase()),typeText=byId('reportTypeFilter').selectedOptions[0]?.textContent||'Todos los tipos',visitors=rows.reduce((s,r)=>s+(Number(r.vis)||0),0),income=rows.reduce((s,r)=>s+(Number(r.total)||0),0),days=new Set(rows.map(r=>r.fecha)).size,subtitle=`${month} · ${typeText} · Solo solicitudes activas (sin rechazadas ni canceladas) · ${VisitasExcel.generatedLabel()}`,daily=groupSummary(rows,r=>r.fecha).sort((a,b)=>a.grupo.localeCompare(b.grupo)).map(item=>({fecha:item.grupo,dia:prettyVisitDate(item.grupo).weekday,solicitudes:item.solicitudes,visitantes:item.visitantes,monto:item.monto}));return VisitasExcel.download(`reporte_visitantes_${key}.xlsx`,[{name:'Reporte',title:`Reporte de visitantes · ${month}`,subtitle,tables:[{caption:'Indicadores del mes',columns:[{header:'Visitantes',key:'visitantes',type:'int'},{header:'Solicitudes',key:'solicitudes',type:'int'},{header:'Días con visitas',key:'dias',type:'int'},{header:'Promedio diario',key:'promedio',type:'int'},{header:'Ingresos por visitas',key:'ingresos',type:'money'}],rows:[{visitantes:visitors,solicitudes:rows.length,dias:days,promedio:days?Math.round(visitors/days):0,ingresos:income}]},{caption:'Por institución',columns:summaryColumns('Institución').map(c=>c.key==='monto'?{...c,header:'Ingresos'}:c),rows:groupSummary(rows,r=>r.inst||'Sin institución').sort((a,b)=>b.visitantes-a.visitantes),totals:{grupo:'Total',solicitudes:'sum',visitantes:'sum',monto:'sum'}},{caption:'Por tipo de visita',columns:summaryColumns('Tipo de visita').map(c=>c.key==='monto'?{...c,header:'Ingresos'}:c),rows:groupSummary(rows,r=>visitTypeLabel(r.tipo)),totals:{grupo:'Total',solicitudes:'sum',visitantes:'sum',monto:'sum'}}]},{name:'Por día',title:`Visitantes por día · ${month}`,subtitle,tables:[{columns:[{header:'Fecha',key:'fecha',type:'date',width:14},{header:'Día',key:'dia',width:12},{header:'Solicitudes',key:'solicitudes',type:'int'},{header:'Visitantes',key:'visitantes',type:'int'},{header:'Ingresos',key:'monto',type:'money'}],rows:daily,totals:{fecha:'Total',solicitudes:'sum',visitantes:'sum',monto:'sum'}}]},{name:'Detalle',title:`Solicitudes de ${month}`,subtitle,freezeColumns:1,tables:[{columns:requestExcelColumns(),rows:sortedRequests(rows).map(requestExcelRow),totals:{id:'Total',vis:'sum',total:'sum'}}]}])})}
async function postAction(payload){const response=await fetch('gestion_solicitud_visita.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...payload,csrf})}),body=await response.json().catch(()=>({}));if(!response.ok||!body.success)throw new Error(body.error||'No fue posible completar la operación.');return body}
function setBusy(button,busy){if(!button)return;if(!button.dataset.idleHtml)button.dataset.idleHtml=button.innerHTML;button.disabled=busy;button.innerHTML=busy?'<i class="ti ti-loader-2 ti-spin" aria-hidden="true"></i>Procesando…':button.dataset.idleHtml}
function renderReview(){
  if(!activeRequest)return;
  const editable=['pendiente','enviado','organizando'].includes(activeRequest.status),approved=['aprobado','notificada'].includes(activeRequest.status),inactive=['rechazado','cancelado','cancelada'].includes(activeRequest.status);
  byId('visitReviewTitle').textContent=`Gestionar visita — solicitud #${activeRequest.id}`;
  byId('visitReviewSummary').innerHTML=`<div><small>Institución</small><strong>${escapeHtml(activeRequest.institution)}</strong></div><div><small>Solicitante</small><strong>${escapeHtml(activeRequest.requester)}</strong></div><div><small>Programación</small><strong>${escapeHtml(activeRequest.date)} · ${escapeHtml(activeRequest.startTime)}</strong></div><div><small>Visitantes</small><strong>${activeRequest.attendees}</strong></div>`;
  byId('visitReviewStatus').innerHTML=`${badge(activeRequest.status,false,activeRequest.id)} ${typeChip(activeRequest.type)}`;
  const areaBox=byId('visitReviewAreas');
  areaBox.innerHTML=activeRequest.areas.length?activeRequest.areas.map(area=>`<div class="visit-review-area"><span><i class="ti ti-map-pin" aria-hidden="true"></i>${escapeHtml(area.name)}</span><div><button type="button" class="visit-button small blue-outline" data-replace-area="${area.originalId}" ${editable?'':'disabled'}><i class="ti ti-replace" aria-hidden="true"></i>Reemplazar</button><button type="button" class="visit-button small danger-outline" data-remove-area="${area.originalId}" ${editable?'':'disabled'}><i class="ti ti-trash" aria-hidden="true"></i>Quitar</button></div></div>`).join(''):'<div class="visit-empty-state">No hay áreas asignadas.</div>';
  byId('addVisitArea').disabled=!editable;
  byId('visitAreasSection').classList.toggle('locked',!editable);
  byId('visitAgendaLabel').textContent=activeRequest.agenda?'Reemplazar archivo de agenda':'Seleccionar archivo de agenda';
  byId('visitAgendaInput').disabled=inactive;
  byId('visitAgendaFiles').innerHTML=activeRequest.agenda?`<div class="visit-file-chip"><i class="ti ti-file-type-pdf" aria-hidden="true"></i><a target="_blank" href="ver_archivo_gestion.php?request_id=${activeRequest.id}&kind=agenda">${escapeHtml(activeRequest.agenda.name)}</a><button type="button" data-delete-agenda title="Quitar agenda"><i class="ti ti-x" aria-hidden="true"></i></button></div>`:'<span class="secondary">Aún no se ha cargado una agenda.</span>';
  const existing=byId('existingRoomRequest'),roomButton=byId('openVisitRoom');
  if(existing&&roomButton){delete roomButton.dataset.idleHtml;if(activeRequest.roomRequest){existing.classList.remove('hidden');existing.innerHTML=`<strong>Solicitud ${escapeHtml(activeRequest.roomRequest.code)}</strong><span>${escapeHtml(activeRequest.roomRequest.space)} · ${escapeHtml(activeRequest.roomRequest.configuration)} · hasta ${escapeHtml(activeRequest.roomRequest.endTime)}</span>`;roomButton.disabled=true;roomButton.innerHTML='<i class="ti ti-circle-check" aria-hidden="true"></i>Salón solicitado'}else{existing.classList.add('hidden');roomButton.disabled=inactive;roomButton.innerHTML='<i class="ti ti-door-enter" aria-hidden="true"></i>Solicitar salón'}}
  const help=byId('directorApprovalHelp'),director=byId('directorApprovalActions');
  if(activeRequest.status==='organizando'){help.textContent='Cuando la agenda, las áreas y el salón estén listos, envía la solicitud al director.';director.innerHTML='<button type="button" class="visit-button primary" data-send-director><i class="ti ti-send" aria-hidden="true"></i>Enviar a aprobación del director</button>'}
  else if(activeRequest.status==='revision_director'){help.textContent='La solicitud está pendiente de decisión del director.';director.innerHTML='<button type="button" class="visit-button danger-outline" data-director-decision="reject" data-request-id="'+activeRequest.id+'"><i class="ti ti-x" aria-hidden="true"></i>Rechazar</button><button type="button" class="visit-button primary" data-director-decision="approve" data-request-id="'+activeRequest.id+'"><i class="ti ti-check" aria-hidden="true"></i>Aprobar</button>'}
  else if(approved){help.innerHTML='<span class="visit-inline-success"><i class="ti ti-circle-check" aria-hidden="true"></i> Solicitud aprobada por el director.</span>';director.innerHTML=''}
  else{help.textContent=inactive?'La solicitud ya no está activa.':'Primero inicia la organización de la visita.';director.innerHTML=''}
  const areaInfo=activeRequest.areas.length?activeRequest.areas.map(area=>area.name).join(', '):'Sin áreas técnicas asociadas';
  byId('areaNotificationInfo').textContent=areaInfo+(activeRequest.notifications.areas?` · Notificado ${displayDate(activeRequest.notifications.areas)}`:'');
  const areaNotify=byId('notifyVisitAreas');areaNotify.disabled=!activeRequest.areas.length||inactive;areaNotify.querySelector('span').textContent=activeRequest.notifications.areas?'Reenviar':'Notificar';
  const currentRow=findRow(activeRequest.id),isPaid=Number(currentRow?.total||0)>0;
  byId('institutionNotificationTitle').textContent=isPaid?'Institución (confirmación + cotización)':'Institución (confirmación)';
  byId('institutionNotificationInfo').textContent=approved?`${activeRequest.institution} · ${activeRequest.email}${activeRequest.notifications.institution?' · Enviado '+displayDate(activeRequest.notifications.institution):''}`:'Disponible cuando el director apruebe la solicitud.';
  const institutionNotify=byId('notifyVisitInstitution');institutionNotify.disabled=!approved;institutionNotify.querySelector('span').textContent=activeRequest.notifications.institution?'Reenviar':(isPaid?'Enviar confirmación y cotización':'Enviar confirmación');
  byId('visitPhotosInput').disabled=inactive;
  byId('visitPhotoFiles').innerHTML=activeRequest.photos.length?activeRequest.photos.map(photo=>`<div class="visit-file-chip"><i class="ti ti-photo" aria-hidden="true"></i><a target="_blank" href="ver_archivo_gestion.php?request_id=${activeRequest.id}&kind=photo&id=${photo.id}">${escapeHtml(photo.name)}</a><button type="button" data-delete-photo="${photo.id}" title="Quitar fotografía"><i class="ti ti-x" aria-hidden="true"></i></button></div>`).join(''):'<span class="secondary">Aún no se han subido fotos.</span>';
  byId('visitContactSave').innerHTML=activeRequest.contactSaved?`<div><strong class="visit-inline-success"><i class="ti ti-circle-check" aria-hidden="true"></i> Ya está en la base de datos</strong><small>${escapeHtml(activeRequest.requester)} · ${escapeHtml(activeRequest.institution)} · ${escapeHtml(activeRequest.email)} · ${escapeHtml(activeRequest.phone)}</small></div>`:`<div><strong>${escapeHtml(activeRequest.requester)}</strong><small>${escapeHtml(activeRequest.institution)} · ${escapeHtml(activeRequest.email)} · ${escapeHtml(activeRequest.phone)}</small></div><button type="button" class="visit-button primary" data-save-contact><i class="ti ti-database-plus" aria-hidden="true"></i>Agregar a base de datos</button>`;
}
function defaultEnd(start){const [h,m]=start.split(':').map(Number);return `${String(Math.min(h+1,23)).padStart(2,'0')}:${String(m).padStart(2,'0')}`}
function renderConfigurations(){const space=availableRooms.find(item=>item.id===Number(byId('visitRoomSpace').value)),select=byId('visitRoomConfiguration');select.innerHTML=space?space.configurations.map(item=>`<option value="${item.id}">${escapeHtml(item.name)} · capacidad ${item.capacity}</option>`).join(''):'<option value="">Selecciona un salón</option>';select.disabled=!space;byId('submitVisitRoom').disabled=!space}
async function loadAvailability(){const end=byId('visitRoomEnd').value,message=byId('visitRoomAvailabilityMessage'),space=byId('visitRoomSpace');message.className='availability-message loading';message.textContent='Consultando salones disponibles en CengiSalas…';space.disabled=true;byId('submitVisitRoom').disabled=true;try{const response=await fetch(`cengisalas_salon_visita.php?request_id=${activeRequest.id}&end_time=${encodeURIComponent(end)}`),body=await response.json().catch(()=>({}));if(!response.ok||!body.success)throw new Error(body.error||'No fue posible consultar disponibilidad.');availableRooms=body.spaces||[];space.innerHTML=availableRooms.length?'<option value="">Seleccionar salón</option>'+availableRooms.map(item=>`<option value="${item.id}">${escapeHtml(item.name)}</option>`).join(''):'<option value="">No hay salones disponibles</option>';space.disabled=!availableRooms.length;message.className='availability-message '+(availableRooms.length?'success':'warning');message.textContent=availableRooms.length?`${availableRooms.length} ${availableRooms.length===1?'salón disponible':'salones disponibles'} para este horario.`:'No hay salones con capacidad suficiente disponibles en ese horario.';renderConfigurations()}catch(error){availableRooms=[];space.innerHTML='<option value="">Sin disponibilidad</option>';message.className='availability-message error';message.textContent=error.message}}
