const contactActionButtons=(item,kind)=>{const mail=item.email?`<a class="icon-btn" href="mailto:${encodeURIComponent(item.email)}" title="Escribir correo" aria-label="Escribir correo a ${escapeHtml(item.name)}"><i class="ti ti-mail" aria-hidden="true"></i></a>`:'';const phone=item.phone?`<a class="icon-btn" href="tel:${escapeHtml(item.phone.replace(/[^0-9+]/g,''))}" title="Llamar" aria-label="Llamar a ${escapeHtml(item.name)}"><i class="ti ti-phone" aria-hidden="true"></i></a>`:'';let edit='';if(canManageContacts&&contactsReady){if(kind==='interno'&&item.source==='area')edit=byId('navAreas')?`<button type="button" class="icon-btn" data-goto-areas title="Se edita en Áreas de visita" aria-label="Editar en Áreas de visita"><i class="ti ti-settings" aria-hidden="true"></i></button>`:'';else edit=`<button type="button" class="icon-btn" data-contact-edit="${kind}" data-contact-key="${escapeHtml(contactKey(item))}" title="Editar contacto" aria-label="Editar a ${escapeHtml(item.name)}"><i class="ti ti-edit" aria-hidden="true"></i></button>`}return `<div class="contact-actions">${mail}${phone}${edit}</div>`};
const contactKey=item=>item.contactId?`id:${item.contactId}`:`mail:${String(item.email||'').toLowerCase()}`;
function areaPersonActions(item,isResponsible,area){const mail=item.email?`<a class="icon-btn" href="mailto:${encodeURIComponent(item.email)}" title="Escribir correo" aria-label="Escribir correo a ${escapeHtml(item.name)}"><i class="ti ti-mail" aria-hidden="true"></i></a>`:'';const phone=item.phone?`<a class="icon-btn" href="tel:${escapeHtml(item.phone.replace(/[^0-9+]/g,''))}" title="Llamar" aria-label="Llamar a ${escapeHtml(item.name)}"><i class="ti ti-phone" aria-hidden="true"></i></a>`:'';let edit='';if(isResponsible){if(canEditAreas&&area)edit=`<button type="button" class="icon-btn" ${areaEditAttrs(area)} title="El responsable se edita junto con el área" aria-label="Editar responsable de ${escapeHtml(area.name)}"><i class="ti ti-edit" aria-hidden="true"></i></button>`}else if(canManageContacts&&contactsReady){edit=`<button type="button" class="icon-btn" data-contact-edit="interno" data-contact-key="${escapeHtml(contactKey(item))}" title="Editar contacto" aria-label="Editar a ${escapeHtml(item.name)}"><i class="ti ti-edit" aria-hidden="true"></i></button>`}return `<div class="contact-actions">${mail}${phone}${edit}</div>`}
const areaEditAttrs=area=>`data-edit-area="${area.id}" data-area-name="${escapeHtml(area.name)}" data-area-professional="${escapeHtml(area.professional)}" data-area-email="${escapeHtml(area.email)}" data-area-status="${area.active?1:0}"`;
function areaPersonRow(item,isResponsible,area){const notify=isResponsible?Boolean(item.email):item.notify&&Boolean(item.email);return `<li class="area-person${isResponsible?' responsible':''}"><div class="area-person-main"><strong>${isResponsible?'<span class="star" aria-hidden="true">★</span> ':''}${escapeHtml(item.name)}</strong>${isResponsible?' <span class="source-badge area">Responsable</span>':(item.role?` <span class="area-person-role">${escapeHtml(item.role)}</span>`:'')}<small>${escapeHtml(item.email||'Sin correo')}${item.phone?` · ${escapeHtml(item.phone)}`:''}</small>${item.notes?`<small class="contact-note" title="${escapeHtml(item.notes)}">${escapeHtml(item.notes)}</small>`:''}</div><span class="notify-state ${notify?'':'off'}">${notify?'Recibe avisos':'No recibe avisos'}</span>${areaPersonActions(item,isResponsible,area)}</li>`}
function renderAreas(){const box=byId('areaCards');if(!box)return;const query=normalizeText(byId('areaSearchInput')?.value.trim()||''),status=byId('areaStatusFilter')?.value||'activas',manual=internalContacts.filter(item=>item.source==='manual'),known=new Set(visitAreas.map(area=>area.id));let areas=visitAreas.filter(area=>status==='todas'||(status==='activas'?area.active:!area.active)).map(area=>({area,contacts:manual.filter(item=>item.areaId===area.id)}));const orphans=manual.filter(item=>!item.areaId||!known.has(item.areaId));if(orphans.length&&status!=='inactivas')areas.push({area:null,contacts:orphans});const matches=text=>!query||normalizeText(text).includes(query);areas=areas.map(group=>{const areaText=group.area?`${group.area.name} ${group.area.professional} ${group.area.email}`:'sin area';if(matches(areaText))return group;const contacts=group.contacts.filter(item=>matches(`${item.name} ${item.email} ${item.phone||''} ${item.role||''} ${item.notes||''}`));return contacts.length?{...group,contacts}:null}).filter(Boolean);const people=areas.reduce((sum,group)=>sum+group.contacts.length+(group.area&&group.area.professional?1:0),0),notified=areas.reduce((sum,group)=>sum+group.contacts.filter(item=>item.notify&&item.email).length+(group.area&&group.area.email?1:0),0),areaCount=areas.filter(group=>group.area).length;byId('areaResultCount').textContent=`${areaCount} ${areaCount===1?'área':'áreas'} · ${people} ${people===1?'persona':'personas'} · ${notified} ${notified===1?'recibe':'reciben'} avisos`;if(!areas.length){box.innerHTML=`<div class="empty-state"><i class="ti ti-map-pin-off" aria-hidden="true"></i>${visitAreas.length?'No hay áreas ni contactos con esos criterios.':'No hay áreas configuradas. Agrega la primera área para mostrarla en el formulario.'}</div>`;return}box.innerHTML=areas.map(({area,contacts})=>{if(!area)return `<article class="area-card orphan"><header><div><h3>Sin área asignada</h3><small>Contactos cuya área fue eliminada. Edítalos para asignarles un área.</small></div></header><ul class="area-people">${contacts.map(item=>areaPersonRow(item,false,null)).join('')}</ul></article>`;const responsible={name:area.professional||'Sin responsable asignado',email:area.email,phone:''},count=contacts.filter(item=>item.notify&&item.email).length+(area.email?1:0),warning=!area.email?'<li class="area-warning">Esta área no tiene correo: su responsable no recibirá avisos de visitas.</li>':'';return `<article class="area-card${area.active?'':' inactive'}"><header><div><h3>${escapeHtml(area.name)}</h3><span class="badge ${area.active?'aprobado':'cancelada'}">${area.active?'Activa':'Inactiva'}</span><small>${count} ${count===1?'recibe':'reciben'} avisos</small></div><div class="area-card-actions">${canEditAreas?`<button type="button" class="btn" ${areaEditAttrs(area)}><i class="ti ti-edit" aria-hidden="true"></i> Editar área</button>`:''}${canManageContacts&&contactsReady?`<button type="button" class="btn" data-contact-new="interno" data-area-id="${area.id}"><i class="ti ti-user-plus" aria-hidden="true"></i> Contacto</button>`:''}</div></header><ul class="area-people">${areaPersonRow(responsible,true,area)}${warning}${contacts.map(item=>areaPersonRow(item,false,area)).join('')}${contacts.length?'':'<li class="area-empty">Sin contactos adicionales.</li>'}</ul></article>`}).join('')}
function filteredContactDatabase(){const query=normalizeText(byId('databaseSearchInput').value.trim()),source=byId('databaseSourceFilter')?.value||'';return requesterContacts.filter(item=>(!source||(source==='manual'?['manual','ambos'].includes(item.source):['solicitud','ambos'].includes(item.source)))&&(!query||normalizeText(`${item.name} ${item.institution} ${item.email} ${item.phone} ${item.role||''} ${item.notes||''}`).includes(query)))}
const SOURCE_LABEL={solicitud:'Solicitudes',manual:'Manual',ambos:'Solicitudes · editado'};
function displayDate(value){if(!value)return 'Sin fecha';const date=new Date(String(value).replace(' ','T'));return Number.isNaN(date.getTime())?String(value).slice(0,10):new Intl.DateTimeFormat('es-GT',{dateStyle:'medium'}).format(date)}
function renderContactDatabase(){const rows=filteredContactDatabase();byId('databaseResultCount').textContent=`${rows.length} ${rows.length===1?'contacto encontrado':'contactos encontrados'}`;byId('databaseBody').innerHTML=rows.length?rows.map(item=>`<tr><td><strong>${escapeHtml(item.name)}</strong>${item.role?`<span class="contact-note">${escapeHtml(item.role)}</span>`:''}${item.notes?`<span class="contact-note" title="${escapeHtml(item.notes)}">${escapeHtml(item.notes)}</span>`:''}</td><td>${escapeHtml(item.institution||'—')}</td><td>${escapeHtml(item.email||'—')}</td><td>${escapeHtml(item.phone||'Sin teléfono')}</td><td>${item.requests}</td><td>${item.lastRequest?escapeHtml(displayDate(item.lastRequest)):'—'}</td><td><span class="source-badge ${item.source}">${SOURCE_LABEL[item.source]||'Solicitudes'}</span></td><td style="text-align:center">${contactActionButtons(item,'externo')}</td></tr>`).join(''):`<tr><td colspan="8"><div class="empty-state"><i class="ti ti-database-off" aria-hidden="true"></i>No se encontraron contactos.${canManageContacts&&contactsReady?' <button type="button" class="btn" data-contact-new="externo" style="margin-left:8px">Agregar contacto</button>':''}</div></td></tr>`}
