byId('exportVisitorExcel')?.addEventListener('click',event=>exportVisitorExcel(event.currentTarget.dataset.requestId,event.currentTarget));
function clearRequestFilters(){byId('searchInput').value='';byId('statusFilter').value='todas';byId('typeFilter').value='todos';['paymentFilter'].forEach(id=>{if(byId(id))byId(id).value='todos'});['dateFromFilter','dateToFilter'].forEach(id=>{if(byId(id))byId(id).value=''});refreshRequests()}
document.addEventListener('click',event=>{const tab=event.target.closest('[data-status-tab]');if(tab){byId('statusFilter').value=tab.dataset.statusTab;refreshRequests();return}const sort=event.target.closest('.sort-btn[data-sort]');if(sort){const key=sort.dataset.sort;requestSort=requestSort.key===key?{key,dir:requestSort.dir==='asc'?'desc':'asc'}:{key,dir:key==='nombre'?'asc':'desc'};refreshRequests();return}const page=event.target.closest('#requestPager [data-page]');if(page&&!page.disabled){requestPage=Number(page.dataset.page);renderTable();byId('viewSolicitudes')?.scrollIntoView({behavior:'smooth',block:'start'});return}if(event.target.closest('#clearRequestFilters,[data-clear-filters]'))clearRequestFilters()});
byId('dateFromFilter')?.addEventListener('change',()=>{const from=byId('dateFromFilter'),to=byId('dateToFilter');to.min=from.value||'';if(from.value&&to.value&&to.value<from.value)to.value=from.value});
async function postVisitFiles(action,files=[],extra={}){const form=new FormData();form.append('csrf',csrf);form.append('action',action);form.append('request_id',activeRequest.id);Object.entries(extra).forEach(([key,value])=>form.append(key,value));if(action==='upload_photos')Array.from(files).forEach(file=>form.append('files[]',file));else if(files[0])form.append('file',files[0]);const response=await fetch('gestion_archivos_visita.php',{method:'POST',body:form}),body=await response.json().catch(()=>({}));if(!response.ok||!body.success)throw new Error(body.error||'No fue posible procesar el archivo.');return body}
function mailtoUrl(to,subject,body){return `mailto:${encodeURIComponent(to)}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`}
byId('visitAgendaInput')?.addEventListener('change',async event=>{if(!event.target.files.length)return;try{await postVisitFiles('upload_agenda',event.target.files);notify('Agenda cargada correctamente.');setTimeout(()=>location.reload(),650)}catch(error){notify(error.message,true);event.target.value=''}});
byId('visitPhotosInput')?.addEventListener('change',async event=>{if(!event.target.files.length)return;try{await postVisitFiles('upload_photos',event.target.files);notify('Fotografías cargadas correctamente.');setTimeout(()=>location.reload(),650)}catch(error){notify(error.message,true);event.target.value=''}});
document.addEventListener('click',async event=>{
  const sendDirector=event.target.closest('[data-send-director]');if(sendDirector){setBusy(sendDirector,true);try{await postAction({action:'send_director',request_id:activeRequest.id});notify('Solicitud enviada a aprobación del director.');setTimeout(()=>location.reload(),600)}catch(error){notify(error.message,true);setBusy(sendDirector,false)}return}
  const director=event.target.closest('[data-director-decision]');if(director){const decision=director.dataset.directorDecision,label=decision==='approve'?'aprobar':'rechazar';if(!confirm(`¿Confirmas que deseas ${label} esta solicitud?`))return;setBusy(director,true);try{await postAction({action:'change_status',request_id:Number(director.dataset.requestId),decision});notify(`Solicitud ${decision==='approve'?'aprobada':'rechazada'}.`);setTimeout(()=>location.reload(),600)}catch(error){notify(error.message,true);setBusy(director,false)}return}
  const deleteAgenda=event.target.closest('[data-delete-agenda]');if(deleteAgenda){if(!confirm('¿Quitar la agenda cargada?'))return;setBusy(deleteAgenda,true);try{await postVisitFiles('delete_agenda');location.reload()}catch(error){notify(error.message,true);setBusy(deleteAgenda,false)}return}
  const deletePhoto=event.target.closest('[data-delete-photo]');if(deletePhoto){if(!confirm('¿Quitar esta fotografía?'))return;setBusy(deletePhoto,true);try{await postVisitFiles('delete_photo',[],{photo_id:deletePhoto.dataset.deletePhoto});location.reload()}catch(error){notify(error.message,true);setBusy(deletePhoto,false)}return}
  const saveContact=event.target.closest('[data-save-contact]');if(saveContact){setBusy(saveContact,true);try{await postAction({action:'save_contact',request_id:activeRequest.id});activeRequest.contactSaved=true;renderReview();notify('Contacto agregado a la base de datos.')}catch(error){notify(error.message,true);setBusy(saveContact,false)}return}
});
byId('notifyVisitAreas')?.addEventListener('click',async event=>{const emails=[...new Set(internalContacts.filter(contact=>contact.notify!==false&&activeRequest.areas.some(area=>area.name===contact.area)).map(contact=>contact.email).filter(Boolean))];if(!emails.length)return notify('No hay correos asignados a estas áreas. Agrégalos en Contactos.',true);setBusy(event.currentTarget,true);try{await postAction({action:'notify_areas',request_id:activeRequest.id});const subject=`Visita a Cengicaña — solicitud #${activeRequest.id}`,body=`Estimados:\n\nSe les notifica la visita de ${activeRequest.institution}, programada para el ${activeRequest.date} a las ${activeRequest.startTime}.\n\nÁreas: ${activeRequest.areas.map(area=>area.name).join(', ')}.\n\nSaludos.`;window.location.href=mailtoUrl(emails.join(','),subject,body);notify('Notificación preparada para las áreas.');setTimeout(()=>location.reload(),900)}catch(error){notify(error.message,true);setBusy(event.currentTarget,false)}});
byId('notifyVisitInstitution')?.addEventListener('click',async event=>{setBusy(event.currentTarget,true);try{await postAction({action:'notify_institution',request_id:activeRequest.id});const paid=activeRequest.type!=='cengicana',row=findRow(activeRequest.id),subject=`Confirmación de visita${paid?' y cotización':''} — solicitud #${activeRequest.id}`,body=`Estimado(a) ${activeRequest.requester}:\n\nSu visita fue aprobada para el ${activeRequest.date} a las ${activeRequest.startTime}.${paid&&row?`\n\nCotización estimada: Q${row.total.toFixed(2)}`:''}\n\nSaludos.`;window.location.href=mailtoUrl(activeRequest.email,subject,body);notify('Confirmación preparada para la institución.');setTimeout(()=>location.reload(),900)}catch(error){notify(error.message,true);setBusy(event.currentTarget,false)}});
function openAreaEditor(button=null){const form=byId('areaEditorForm');if(!form)return;const editing=Boolean(button);form.action=editing?'modulos/editar_area.php':'modulos/guardar_area.php';byId('areaEditorTitle').textContent=editing?'Editar área':'Agregar área';byId('areaEditorId').value=editing?button.dataset.editArea:'';byId('areaEditorName').value=editing?button.dataset.areaName:'';byId('areaEditorProfessional').value=editing?button.dataset.areaProfessional:'';byId('areaEditorEmail').value=editing?button.dataset.areaEmail:'';byId('areaEditorStatus').value=editing?(button.dataset.areaStatus||'1'):'1';byId('areaEditorStatusField').hidden=!editing;showModal('areaEditorModal')}
