document.addEventListener('click',event=>{const create=event.target.closest('[data-contact-new]');if(create){openContactEditor(create.dataset.contactNew,null,create.dataset.areaId||'');return}const edit=event.target.closest('[data-contact-edit]');if(edit){const item=findContact(edit.dataset.contactEdit,edit.dataset.contactKey);if(item)openContactEditor(edit.dataset.contactEdit,item);return}if(event.target.closest('[data-goto-areas]'))switchTab('areas')});
byId('contactEditorForm')?.addEventListener('submit',saveContact);
byId('contactEditorDelete')?.addEventListener('click',deleteContact);
populateMonths();renderTable();
{const requested=<?= json_encode((string) ($_GET['vista'] ?? ''), $jsonFlags) ?>,saved=sessionStorage.getItem('visitsReturnTab'),notice=sessionStorage.getItem('visitsNotice'),allowed=['solicitudes','contactos','areas','basedatos','roles'];sessionStorage.removeItem('visitsReturnTab');sessionStorage.removeItem('visitsNotice');const tab=[saved,requested].find(value=>allowed.includes(value))||'solicitudes';switchTab(tab);if(notice)notify(notice)}
